const cadd = (u, v) => [u[0] + v[0], u[1] + v[1]], csub = (u, v) => [u[0] - v[0], u[1] - v[1]];
const cmul = (u, v) => [u[0] * v[0] - u[1] * v[1], u[0] * v[1] + u[1] * v[0]];
const conj = u => [u[0], -u[1]];
